try{if(location.hash.startsWith('#draft=')||location.hash.startsWith('#draft2=')){state=await decodeShare(location.hash);state.id=uid();sharedLoaded=true;history.replaceState(null,'',location.pathname+location.search)}}catch{setTimeout(()=>toast(L('草稿链接无法打开，请用导出的 JSON 文件恢复。','The draft link could not be opened. Restore it from an exported JSON file.')),500)}
