 const root=$('#composition');root.innerHTML=state.items.map(i=>{const name=assetName(assetById[i.type]);return `<div class="stem ${i.id===selected?'selected':''}" data-id="${i.id}" style="${stemStyle(i)}" role="button" tabindex="0" aria-label="${esc(L(`${name}，拖动移动，双指旋转缩放`,`${name}; drag to move, use two fingers to rotate and scale`))}" aria-pressed="${i.id===selected}"><canvas class="specimen-image" aria-hidden="true"></canvas></div>`}).join('');
 for(const i of state.items){drawStemCanvas($(`.stem[data-id="${i.id}"]`),i)}
