function addSpecimen(type,placement='front'){if(state.items.length>=24)return toast(L('先让这 24 枝找到自己的位置，再添加。','Arrange these 24 stems before adding another.'));checkpoint();const insertion=vesselGeometry(assetById[state.vessel]).insertion,item=makeItem(type,{x:insertion[0],y:insertion[1],angle:0});if(placement==='back')state.items.unshift(item);else state.items.push(item);selected=item.id;setEditMode('move');renderStage();ensureAsset(type).then(()=>{if(state.items.some(i=>i.id===item.id))renderStage()}).catch(()=>toast(L('这枝花材暂时无法载入。','This material could not be loaded.')));persist();const name=assetName(assetById[type]);toast(L(`添入一枝${name}，放在${placement==='back'?'最后层':'最前层'}`,`Added ${name} to the ${placement==='back'?'back':'front'} layer`))}
