$('#stage').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeLayerMenu();setEditMode('move');renderStage();return}if(e.target.closest('input,textarea'))return;if(e.key==='Enter'&&e.target.closest('.stem')){selectItem(e.target.closest('.stem').dataset.id);return}const item=current();if(!item)return;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeSelected();return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();checkpoint();const step=e.shiftKey?2:.5;item.x=clamp(item.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),5,95);item.y=clamp(item.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0),15,95);const el=$(`.stem[data-id="${item.id}"]`);if(el)el.style.cssText=stemStyle(item);persist()});
for(const [id,key,factor] of [['angle','angle',1],['size','h',1],['trim','trim',1],['length','length',.01]]){let active=false;const el=$('#'+id);el.addEventListener('input',()=>{const item=current();if(!item)return;if(!active){checkpoint();active=true}item[key]=+el.value*factor;renderStage();persist()});el.addEventListener('change',()=>active=false);el.addEventListener('blur',()=>active=false)}
function removeSelected(){if(!current())return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);selected=state.items.at(-1)?.id||null;setEditMode('move');renderStage();persist()}
$('#delete-button').onclick=removeSelected;$('#flip-button').onclick=()=>{if(!current())return;checkpoint();current().flip=!current().flip;renderStage();persist()};$('#layer-button').onclick=()=>{let item=current();if(!item)return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);state.items.push(item);renderStage();persist();toast(L('已移到最前层','Moved to the front layer'))};
$('#undo-button').onclick=()=>{finishMoveInteraction(true);if(!undoStack.length)return;redoStack.push({state:clone(state),selected});const previous=undoStack.pop();state=previous.state;selected=previous.selected;setEditMode('move');renderAll()};$('#redo-button').onclick=()=>{finishMoveInteraction(true);if(!redoStack.length)return;undoStack.push({state:clone(state),selected});const next=redoStack.pop();state=next.state;selected=next.selected;setEditMode('move');renderAll()};
$('#guide-button').onclick=()=>{const on=$('#guide').hidden;$('#guide').hidden=!on;$('#guide-button').setAttribute('aria-pressed',String(on))};$('#reset-button').onclick=()=>{checkpoint();state.items=[];selected=null;setEditMode('move');renderStage();persist();toast(L('花器已留空，随时可以撤销。','The vessel is empty. You can undo this action.'))};
$$('[data-scene]').forEach(b=>b.onclick=()=>{checkpoint();state.scene=b.dataset.scene;renderStage();persist()});$$('[data-mood]').forEach(b=>b.onclick=()=>{checkpoint();state.mood=b.dataset.mood;$$('[data-mood]').forEach(t=>t.classList.toggle('active',t===b));persist()});
$('#work-title').addEventListener('input',e=>{state.title=e.target.value;persist()});$('#intention').addEventListener('input',e=>{state.intention=e.target.value;persist()});
$('#generation-mode').onchange=e=>{checkpoint();state.generation=e.target.value;$('#generation-mode-help').textContent=generationDescriptions[lang][state.generation];persist()};

function openModal(html,kicker='HANAMA ATELIER'){$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;icons($('#modal'));if(!$('#modal').open)$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function help(){const html=lang==='en'?`<h2>Take a moment and arrange slowly.</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>Choose and place.</strong><br>Select plants and a vessel. Choose a natural color and pose, then place new material at the front or back. Drag to move; on touch screens, use two fingers to rotate and scale. Right-click the canvas or open Layers to reorder. Size and stem length adjust independently, and the pruning tools remove selected foliage.</p></div><div><span class="step-number">02</span><p><strong>Set your intention.</strong><br>Choose the scene and add a note. All three modes preserve your flowers, main composition and overall light. They allow different degrees of small adjustments to stem curves, facing, depth and insertion so the sketch becomes a believable real arrangement.</p></div><div><span class="step-number">03</span><p><strong>From draft to artwork.</strong><br>Download the pack, upload draft.png to ChatGPT image creation or GPT Image, and paste prompt.txt. The composition guide is optional. Import the result into My Works to save or share it.</p></div></div><p class="file-note">Keyboard: use arrow keys to nudge, Shift + arrows for larger moves, and Delete to remove the selected material. Drafts and artworks stay in this browser unless you export them.</p><div class="modal-actions"><button class="button dark" id="help-done">Start arranging</button><button class="button outline" id="help-import">Import draft file</button></div>`:`<h2>给自己一刻，慢慢插花。</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>选花，落枝。</strong><br>点选左侧花材和花器。挑选自然花色与姿态，并决定新花材放在最前层或最后层。单指拖动调整位置，双指旋转和缩放；右键画布或点击图层按钮可以调整前后顺序。花材大小和枝梗长度可分别调整，也可以圈选剪枝或细部擦除。</p></div><div><span class="step-number">02</span><p><strong>写下你的意境。</strong><br>选择光与景，留下一句话。三种生成方式都保留用花、主要构图与整体光感，允许不同程度的小幅整理：枝条弧度、花面朝向、前后空间和瓶口插入关系。</p></div><div><span class="step-number">03</span><p><strong>从草稿，到作品。</strong><br>下载创作包，在 ChatGPT 图片创作或 GPT Image 中上传 draft.png，再粘贴 prompt.txt。轮廓参考图可按需附上。生成后可导入「我的作品」保存或分享。</p></div></div><p class="file-note">键盘操作：方向键微调，Shift + 方向键大幅移动，Delete 删除。草稿与成品仅保存在当前浏览器，导出文件可以备份。</p><div class="modal-actions"><button class="button dark" id="help-done">开始这一枝</button><button class="button outline" id="help-import">导入草稿文件</button></div>`;openModal(html);$('#help-done').onclick=()=>$('#modal').close();$('#help-import').onclick=()=>$('#draft-upload').click()}
$('#help-button').onclick=help;
function sources(){const html=lang==='en'?`<h2>Materials from nature, ideas from ikebana.</h2><p>Hanama is a free-form creative exercise. It does not score work or present its simplified composition hints as school rules.</p><h3>Ikebana references</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">Ikenobo · Three styles of ikebana ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">Sogetsu · Learning through free expression ↗</a></div><p>Ikenobo free style values the form and texture of plants; Sogetsu encourages personal expression. The spacing and direction cues here are creative suggestions for the game.</p><h3>The Flower Book · reading notes</h3><p>Rachel Siegfried, DK: vessel shape (pp. 10–11), floral roles and natural facing (pp. 12–21), cherry (pp. 64–67), iris (pp. 108–111), and chrysanthemum (pp. 156–159). The editable studies interpret these ideas. Six botanical assets adapt photographs supplied from the book: anemone, hellebore, ranunculus, tulip, iris and peony. GPT Image removed the page layout and completed the stems; these are adaptations, not untouched extracts.</p><h3>Asset notes</h3><p>Apart from the labeled book adaptations, plant variants and newer vessels are original GPT Image assets. Two original vessels come from <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>, marked CC0 on the source page. The archived exhibition photograph is Rémi Jouan's <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>, used under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>.</p><p class="file-note">Sources reviewed September 2026. You control exports and sharing; Hanama does not publish your images automatically.</p>`:`<h2>从自然取材，从花道取意。</h2><p>花间以自由创作练习为出发点，不为作品打分，也不将简化的构图方法当作流派规范。</p><h3>花道参考</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">池坊 · 花道的三种样式 ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">草月 · 自由表达与学习 ↗</a></div><p>池坊的自由花重视草木的形状与质感；草月鼓励创作者表达自己的想法。这里的留白、方向和疏密提示，是游戏中的创作建议。</p><h3>《The Flower Book》阅读手记</h3><p>Rachel Siegfried 著，DK 出版：花器形态（书页 10–11）、花材主次与自然朝向（12–21）、樱枝（64–67）、鸢尾（108–111）、菊花（156–159）。可编辑练习重新诠释这些思路。另有六款花材取自用户提供的书中实拍照片：银莲花、铁筷子、花毛茛、郁金香、鸢尾、芍药，经 GPT Image 去除版面并补全枝梗，并非原图的无损提取。</p><h3>素材说明</h3><p>除标注的「书图整理」外，其余花枝与自然花色、姿态素材使用 GPT Image 原创生成。新增花器也使用 GPT Image 原创生成；原有两只花器来自 <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>，来源页标注 CC0。保留的展览参考摄影为 Rémi Jouan 的 <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>，依据 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> 使用。</p><p class="file-note">资料整理：2026 年 9 月。你的作品由你导出和分享；本工房不自动公开上传图片。</p>`;openModal(html,'REFERENCES & MATERIALS')}
$('#sources-button').onclick=sources;
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error(L('图片暂时无法载入，请稍后重试','The image could not be loaded. Please try again.')));img.src=src})}
const imageTasks=new Map();
function ensureAsset(id){if(images[id])return Promise.resolve(images[id]);if(!imageTasks.has(id)){imageTasks.set(id,loadImage(assetPath(id)).then(img=>{images[id]=img;return img}).catch(err=>{imageTasks.delete(id);throw err}))}return imageTasks.get(id)}
const assetsReady=Promise.allSettled([...new Set([...state.items.map(i=>i.type),state.vessel])].map(ensureAsset));
assetsReady.then(results=>{renderStage();if(results.some(r=>r.status==='rejected'))toast(L('部分花材未载入；已载入的花材仍可使用。','Some materials did not load; the available materials can still be used.'))});
function drawCover(ctx,img,x,y,w,h){const factor=Math.max(w/img.width,h/img.height),iw=img.width*factor,ih=img.height*factor;ctx.drawImage(img,x+(w-iw)/2,y+(h-ih)/2,iw,ih)}
async function draftCanvas(s=state,size=1600){
 await Promise.all([...new Set([...s.items.map(i=>i.type),s.vessel])].map(ensureAsset));
 const c=document.createElement('canvas');c.width=c.height=size;
 paintArrangement(c.getContext('2d'),size,s,assetById,scenes,specimenCanvas,images);return c;
}
async function compositionGuideCanvas(s=state,size=1600){
 await Promise.all([...new Set([...s.items.map(i=>i.type),s.vessel])].map(ensureAsset));const c=document.createElement('canvas');c.width=c.height=size;paintCompositionGuide(c.getContext('2d'),size,s,assetById,scenes,specimenCanvas,images);return c;
}
const canvasBlob=(c,type='image/png',quality=.95)=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error(L('无法导出图片，请重试','The image could not be exported. Please try again.'))),type,quality));
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const fileTitle=s=>(s.title||'花间作品').replace(/[\\/:*?"<>|]/g,'-');
const promptFor=(s=state)=>buildPrompt(s,assetById,scenes);
function crc32(data){let c=0xffffffff;for(const v of data){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
async function zipFiles(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;for(const [name,blob] of files){const data=new Uint8Array(await blob.arrayBuffer()),filename=enc.encode(name),crc=crc32(data),local=new Uint8Array(30+filename.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x0800,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,filename.length,true);local.set(filename,30);parts.push(local,data);const cd=new Uint8Array(46+filename.length),dv=new DataView(cd.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x0800,true);dv.setUint32(16,crc,true);dv.setUint32(20,data.length,true);dv.setUint32(24,data.length,true);dv.setUint16(28,filename.length,true);dv.setUint32(42,offset,true);cd.set(filename,46);central.push(cd);offset+=local.length+data.length}const length=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,length,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast(L('已复制','Copied'))}catch{const ta=document.createElement('textarea');ta.value=text;$('#modal').open?$('#modal-content').append(ta):document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?L('已复制','Copied'):L('请长按或选中文字后手动复制','Select the text and copy it manually'))}}
async function generatePackageV3(){
 if(!state.items.length){toast(L('先添入一枝花，再让灵感开花。','Add at least one material before creating a generation pack.'));return}
 const snapshot=clone(state),promptSnapshot={...snapshot,generationVariation:Date.now()},promptText=promptFor(promptSnapshot),modeName=({zh:{natural:'小幅自然重整',creative:'适度花艺润色',faithful:'最小修正'},en:{natural:'Gentle natural refinement',creative:'Moderate florist refinement',faithful:'Minimal correction'}})[lang][snapshot.generation||'natural'];
 const modalHtml=lang==='en'?`<h2>Bring your draft into real life.</h2><p>Keep your flowers, main composition and overall light. Allow small changes to curves, facing, depth and insertion to make a physically believable arrangement.</p><div class="export-preview export-preview-v3"><div class="reference-pair"><figure><img id="draft-preview" alt="Design, materials and overall lighting reference"><figcaption>Design reference</figcaption></figure><figure><img id="guide-preview" alt="Broad silhouette and depth reference"><figcaption>Optional silhouette reference</figcaption></figure></div><div><strong>${esc(snapshot.title||'Untitled Arrangement')}</strong><p>${snapshot.items.length} materials · ${esc(assetName(assetById[snapshot.vessel]))}<br>Mood: ${esc(moodName(snapshot.mood))}<br>Refinement: ${esc(modeName)}</p><p class="file-note">Keep every flower; refine its position and facing gently.<br>Physical realism takes priority over tracing the draft.</p></div></div><label for="prompt-text" class="slider-label">Generation prompt</label><textarea id="prompt-text" class="prompt-area" readonly></textarea><div class="modal-actions"><button class="button accent" id="download-package" disabled><span data-icon="download"></span>Download .zip pack</button><button class="button outline" id="copy-prompt" disabled><span data-icon="copy"></span>Copy Prompt</button><button class="button outline" id="import-result" disabled><span data-icon="upload"></span>Import Result</button></div><p class="file-note">Upload draft.png and paste the prompt. Add composition-guide.png if the intended layers are unclear; its contours are approximate.</p>`:`<h2>让草稿，成为真实的插花。</h2><p>保留用花、主要构图和整体光感，允许小幅整理枝条弧度、花面朝向、前后空间与瓶口连接，让作品符合真实物理关系。</p><div class="export-preview export-preview-v3"><div class="reference-pair"><figure><img id="draft-preview" alt="花材、设计与整体光感参考"><figcaption>主要设计参考</figcaption></figure><figure><img id="guide-preview" alt="大致轮廓与前后关系参考"><figcaption>可选轮廓参考</figcaption></figure></div><div><strong>${esc(snapshot.title||'未命名作品')}</strong><p>${snapshot.items.length} 枝花材 · ${esc(assetName(assetById[snapshot.vessel]))}<br>意境：${esc(moodName(snapshot.mood))}<br>整理程度：${esc(modeName)}</p><p class="file-note">保留每一朵花，允许小幅移动与转向。<br>优先修正物理关系，避免照搬拼贴痕迹。</p></div></div><label for="prompt-text" class="slider-label">为你的作品准备的 Prompt</label><textarea id="prompt-text" class="prompt-area" readonly></textarea><div class="modal-actions"><button class="button accent" id="download-package" disabled><span data-icon="download"></span>下载创作包 .zip</button><button class="button outline" id="copy-prompt" disabled><span data-icon="copy"></span>复制 Prompt</button><button class="button outline" id="import-result" disabled><span data-icon="upload"></span>导入生成作品</button></div><p class="file-note">上传 draft.png 并粘贴 Prompt；前后关系不清楚时，可附上 composition-guide.png 辅助说明，无需照描轮廓。</p>`;
 openModal(modalHtml,'DRAFT → GPT IMAGE → ARTWORK');
 $('#prompt-text').value=promptText;const [draft,guide]=await Promise.all([draftCanvas(snapshot),compositionGuideCanvas(snapshot)]);$('#draft-preview').src=draft.toDataURL('image/jpeg',.85);$('#guide-preview').src=guide.toDataURL('image/jpeg',.88);['download-package','copy-prompt','import-result'].forEach(id=>$('#'+id).disabled=false);
 $('#copy-prompt').onclick=()=>copyText(promptText);
 $('#download-package').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const readme="花间 · 自然重整创作包 / HANAMA · NATURAL REFINEMENT PACK\n\n中文\n1. 上传 draft.png 并粘贴 prompt.txt。前后关系不清楚时，可附上 composition-guide.png；它仅作轮廓参考。\n2. 保留用花与花朵数量、主要构图、花器及整体光感。草稿是设计意图，不是必须照描的物理实物。\n3. 允许小幅整理花面、枝条弧度、前后空间和瓶口连接；局部阴影与反光随真实结构修正。\n4. composition.json 可以恢复原始可编辑草稿；生成不会自动改动画布。\n\nENGLISH\n1. Upload draft.png and paste prompt.txt. Optionally add composition-guide.png to clarify intended depth; it is a rough silhouette aid.\n2. Keep the materials and flower count, main composition, vessel and overall light. Treat the draft as design intent rather than exact physical geometry.\n3. Make small corrections to flower facing, stem curves, depth and insertion. Recalculate local shadows and reflections for coherent physical form.\n4. composition.json restores the original editable draft; generation does not automatically modify the canvas.\n\nThe website does not call a generation API and the pack contains no API key.";const zip=await zipFiles([['draft.png',await canvasBlob(draft)],['composition-guide.png',await canvasBlob(guide)],['prompt.txt',new Blob([promptText],{type:'text/plain;charset=utf-8'})],['composition.json',new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})],['readme.txt',new Blob([readme],{type:'text/plain;charset=utf-8'})]]);download(zip,fileTitle(snapshot)+'-'+L('自然重整创作包','natural-refinement-pack')+'.zip');toast(L('创作包已下载，上传草稿图并粘贴 Prompt 即可。','Pack downloaded. Upload the draft and paste the prompt.'))}catch(err){toast(err.message)}finally{b.disabled=false}};
 $('#import-result').onclick=()=>{importArtFor=snapshot;$('#art-upload').click()};
}
$('#generate-button').onclick=()=>generatePackageV3().catch(e=>toast(e.message));$('#export-draft').onclick=async()=>{try{download(await canvasBlob(await draftCanvas()),fileTitle(state)+L('-草稿.png','-draft.png'));toast(L('草稿图已下载','Draft image downloaded'))}catch(e){toast(e.message)}};
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('hanama-artworks',1);req.onupgradeneeded=()=>req.result.createObjectStore('works',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});dbPromise.catch(()=>{});
async function dbAction(mode,fn){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('works',mode);const req=fn(tx.objectStore('works'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error(L('本机存储空间不足或不可用，请导出文件保存。','Local storage is full or unavailable. Export a file to keep your work.')));tx.onabort=()=>reject(Error(L('保存未完成，请导出文件备份。','Saving did not finish. Export a backup file.')))})}
const listWorks=()=>dbAction('readonly',store=>store.getAll());
async function refreshCount(){try{$('#gallery-count').textContent=(await listWorks()).length}catch{}}
async function saveDraft(s=state,{notify=true}={}){const snapshot=clone(s),preview=await canvasBlob(await draftCanvas(snapshot,600),'image/jpeg',.86);const prev=await dbAction('readonly',store=>store.get(snapshot.id));await dbAction('readwrite',store=>store.put({id:snapshot.id,state:snapshot,title:snapshot.title||L('未命名作品','Untitled Arrangement'),updated:Date.now(),preview,art:prev?.art||null}));await refreshCount();if(notify)toast(L('草稿已收进「我的作品」','Draft saved to My Works'));return snapshot.id}
$('#save-button').onclick=async e=>{e.currentTarget.disabled=true;try{await saveDraft()}catch(err){toast(err.message)}finally{$('#save-button').disabled=false}};
const hasMeaningfulCanvas=s=>s.items.length>0||String(s.intention||'').trim()||!['','未命名作品','Untitled Arrangement'].includes(String(s.title||'').trim())||s.vessel!=='round'||s.scene!=='paper'||s.mood!=='静寂'||s.generation!=='natural';
async function activateCanvas(next,{saveCurrent=true,message=''}={}){const activeView=$('.view:not([hidden])');if(activeView)activeView.inert=true;try{const candidate=validate(next);await Promise.all([...new Set([...candidate.items.map(i=>i.type),candidate.vessel])].map(ensureAsset));if(saveCurrent&&hasMeaningfulCanvas(state))await saveDraft(state,{notify:false});state=candidate;selected=state.items.at(-1)?.id||null;undoStack=[];redoStack=[];spriteCache.clear();closeLayerMenu();$('#guide').hidden=true;$('#guide-button').setAttribute('aria-pressed','false');setEditMode('move');renderAll();setView('studio');if(message)toast(message)}finally{if(activeView)activeView.inert=false}}
$('#new-canvas-button').onclick=async e=>{const button=e.currentTarget,hadWork=!!hasMeaningfulCanvas(state),next=initial();next.title=L('未命名作品','Untitled Arrangement');next.intention='';next.items=[];button.disabled=true;try{await activateCanvas(next,{message:hadWork?L('原草稿已保存，新画布已打开。','The previous draft was saved and a new canvas is ready.'):L('新画布已打开。','A new canvas is ready.')})}catch(err){toast(err.message)}finally{button.disabled=false}};
$('#language-toggle').onclick=()=>{lang=lang==='zh'?'en':'zh';try{localStorage.setItem(LANGUAGE_STORE,lang)}catch{}renderAll();const active=$('.view:not([hidden])')?.id;if(active==='inspiration-view')renderInspiration();if(active==='gallery-view')renderGallery().catch(err=>toast(err.message))};
function setView(view){$$('.view').forEach(el=>el.hidden=el.id!==`${view}-view`);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='gallery')renderGallery().catch(err=>toast(err.message));if(view==='inspiration')renderInspiration();window.scrollTo({top:0,behavior:'instant'})}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function studyState(study){
 const pos=vesselGeometry(assetById[study.vessel]).insertion;
 return {...initial(),title:study.title[lang==='en'?1:0],intention:'',vessel:study.vessel,scene:study.scene,mood:study.mood,items:study.items.map(({type,dx=0,dy=0,...options})=>makeItem(type,{x:pos[0]+dx,y:pos[1]+dy,...options}))};
}
function renderInspiration(){
 const index=lang==='en'?1:0,root=$('#inspiration-view');
 root.innerHTML=`<div class="page-heading"><div><p class="eyebrow">THE FLOWER BOOK · FIELD NOTES</p><h1>${L('先看一枝，再想一器。','A stem first. Then a vessel.')}</h1><p>${L('从形态、质感和留白开始。三组搭配，都可以亲手改写。','Start with form, texture and space. Three studies to make your own.')}</p></div><button class="text-button" id="inspiration-sources">${L('阅读与素材来源 ↗','Reading & sources ↗')}</button></div><div class="study-grid">${studies.map((study,i)=>`<article class="study-card"><div class="study-image"><img id="study-preview-${study.id}" alt="${esc(study.title[index])}" hidden><span class="study-number">0${i+1}</span><span class="study-loading">${L('正在铺开花枝…','Preparing the stems…')}</span></div><div class="study-content"><p class="eyebrow">${esc(study.caption[index])}</p><h2>${esc(study.title[index])}</h2><p>${esc(study.note[index])}</p><button class="button outline" data-study="${study.id}">${L('以此开始','Start with this')} <span>↗</span></button></div></article>`).join('')}</div><p class="study-source">${L('阅读 Rachel Siegfried《The Flower Book》（DK）后创作的练习：陶壶与花枝、浅器与线条、暖花与银绿叶。画面为可编辑草稿，其中鸢尾使用书图整理花材，并非生成成品。','Original studies informed by Rachel Siegfried’s The Flower Book (DK): pitchers and branches, shallow vessels and lines, warm flowers and silver foliage. These are editable drafts; the iris uses a book adaptation, not a generated arrangement.')}</p>`;
 $('#inspiration-sources').onclick=sources;
 for(const study of studies){
  const image=$(`#study-preview-${study.id}`),loading=image.parentElement.querySelector('.study-loading'),draft=studyState(study);
  draftCanvas(draft,720).then(canvas=>{if(!image.isConnected)return;image.src=canvas.toDataURL('image/webp',.9);image.hidden=false;loading.remove()}).catch(()=>{if(loading.isConnected)loading.textContent=L('预览暂时无法载入，可点击重试。','Preview unavailable. Select the study to retry.')});
 }
 $$('[data-study]',root).forEach(button=>button.onclick=async()=>{button.disabled=true;try{await activateCanvas(studyState(studies.find(study=>study.id===button.dataset.study)),{message:L('搭配已打开，原草稿已保存在「我的作品」。','Study opened. Your previous draft is in My Works.')})}catch(err){toast(err.message)}finally{button.disabled=false}});
}
async function renderGallery(){
 const works=(await listWorks()).sort((a,b)=>b.updated-a.updated);galleryUrls.forEach(URL.revokeObjectURL);galleryUrls=[];
 const cards=works.map(w=>{const url=URL.createObjectURL(w.art||w.preview);galleryUrls.push(url);const status=w.art?L('生成成品','Generated artwork'):L('插花草稿','Ikebana draft'),date=new Date(w.updated).toLocaleDateString(lang==='en'?'en-US':'zh-CN');return `<article class="art-card"><img src="${url}" alt="${esc(w.title)}" loading="lazy"><div class="art-card-content"><h2>${esc(w.title)}</h2><p>${status} · ${date}</p><div class="art-card-actions"><button data-work-edit="${esc(w.id)}">${L('继续创作','Continue')}</button><button data-work-share="${esc(w.id)}">${L('分享作品 ↗','Share ↗')}</button><button data-work-delete="${esc(w.id)}" aria-label="${esc(L(`删除${w.title}`,`Delete ${w.title}`))}">${L('删除','Delete')}</button></div></div></article>`}).join('');
 $('#gallery-view').innerHTML=`<div class="page-heading"><div><p class="eyebrow">YOUR PERSONAL COLLECTION</p><h1>${L('一花一记','A Record of Each Flower')}</h1><p>${L('这里珍藏你的草稿与成品，仅保存在当前浏览器。','Your drafts and artworks are stored only in this browser.')}</p></div><button class="button outline" id="gallery-import"><span data-icon="upload"></span>${L('导入生成作品','Import Generated Artwork')}</button></div>${works.length?`<div class="gallery-grid">${cards}</div>`:`<div class="empty-gallery"><h2>${L('留住你的第一枝。','Keep your first stem.')}</h2><p>${L('在工房保存草稿，或把生成的成品导入这里。','Save a draft in the atelier or import a generated artwork here.')}</p><button class="button dark" id="back-studio">${L('回到插花台','Back to Atelier')}</button></div>`}`;
 icons($('#gallery-view'));$('#gallery-import').onclick=()=>{importArtFor=clone(state);$('#art-upload').click()};$('#back-studio')?.addEventListener('click',()=>setView('studio'));
 $$('[data-work-edit]').forEach(b=>b.onclick=async()=>{const w=works.find(w=>w.id===b.dataset.workEdit),next=w.id===state.id?clone(state):w.state;b.disabled=true;try{await activateCanvas(next)}catch(err){toast(err.message)}finally{b.disabled=false}});
 $$('[data-work-share]').forEach(b=>b.onclick=()=>shareWork(works.find(w=>w.id===b.dataset.workShare)).catch(err=>toast(err.message)));
 $$('[data-work-delete]').forEach(b=>b.onclick=()=>{const w=works.find(w=>w.id===b.dataset.workDelete);openModal(`<h2>${esc(L(`移除「${w.title}」？`,`Remove “${w.title}”?`))}</h2><p>${L('这会删除本机作品集中的草稿和成品，已下载的图片仍然保留。','This deletes the draft and artwork from this browser. Downloaded files remain.')}</p><div class="modal-actions"><button class="button outline" id="cancel-delete">${L('保留作品','Keep Work')}</button><button class="button accent" id="confirm-delete">${L('删除作品','Delete Work')}</button></div>`);$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=async()=>{try{await dbAction('readwrite',store=>store.delete(w.id));$('#modal').close();await renderGallery();await refreshCount();toast(L('已移除作品','Work removed'))}catch(e){toast(e.message)}}})
}
async function artPoster(w){const c=document.createElement('canvas');c.width=1600;c.height=1870;const ctx=c.getContext('2d');ctx.fillStyle='#f5f2e8';ctx.fillRect(0,0,c.width,c.height);const source=w.art||await canvasBlob(await draftCanvas(w.state,1600));const url=URL.createObjectURL(source);try{const img=await loadImage(url);const fit=Math.min(1480/img.width,1480/img.height);const iw=img.width*fit,ih=img.height*fit;ctx.drawImage(img,60+(1480-iw)/2,60+(1480-ih)/2,iw,ih)}finally{URL.revokeObjectURL(url)}ctx.fillStyle='#354034';ctx.font='48px "Noto Serif SC", "Songti SC", serif';const title=w.title||L('未命名作品','Untitled Arrangement');let label=title;while(ctx.measureText(label).width>1300)label=label.slice(0,-1);if(label!==title)label+='…';ctx.fillText(label,85,1640);ctx.fillStyle='#7a8074';ctx.font='22px sans-serif';ctx.fillText(`${moodName(w.state.mood)}  /  ${w.art?L('由手作草稿延展的生成作品','Generated from a hand-arranged draft'):L('亲手设计的插花草稿','Hand-designed ikebana draft')}`,87,1695);ctx.fillStyle='#a5533e';ctx.font='38px "Songti SC", serif';ctx.fillText(lang==='en'?'HANAMA':'花间',85,1790);ctx.fillStyle='#8e9286';ctx.font='16px sans-serif';ctx.fillText('HANAMA · A MOMENT WITH FLOWERS',lang==='en'?265:200,1787);return canvasBlob(c)}
async function shareWork(w){
 const html=lang==='en'?`<h2>Let this arrangement meet someone.</h2><p>The share card keeps the artwork and title. The draft file lets a friend continue the composition.</p><div class="modal-actions"><button class="button accent" id="share-system" disabled><span data-icon="share"></span>Share Image</button><button class="button outline" id="share-download" disabled><span data-icon="download"></span>Download Share Card</button><button class="button outline" id="share-original">Download ${w.art?'Saved Artwork':'Draft Image'}</button></div><h3>Share an editable draft</h3><p class="file-note">The link carries the material layout and intention, not the generated image. The recipient needs access to this atelier.</p><input class="share-field" id="share-link" readonly aria-label="Draft share link"><div class="modal-actions"><button class="button outline" id="copy-link">Copy Draft Link</button><button class="button outline" id="share-json">Download Draft File</button></div>`:`<h2>让这一枝，遇见别人。</h2><p>分享卡保留作品与题名。草稿文件还能让朋友继续你的创作。</p><div class="modal-actions"><button class="button accent" id="share-system" disabled><span data-icon="share"></span>分享图片</button><button class="button outline" id="share-download" disabled><span data-icon="download"></span>下载分享卡</button><button class="button outline" id="share-original">下载${w.art?'保存的成品':'草稿图'}</button></div><h3>也可以分享可编辑的草稿</h3><p class="file-note">链接仅携带花材布局与意境，不包含成品图片。接收者需要有权访问此工房。</p><input class="share-field" id="share-link" readonly aria-label="草稿分享链接"><div class="modal-actions"><button class="button outline" id="copy-link">复制草稿链接</button><button class="button outline" id="share-json">下载草稿文件</button></div>`;
 openModal(html,'SHARE YOUR LITTLE WORLD');const shared=validate(w.state);shared.id='shared';const hash=await encodeShare(shared);const linkOK=hash.length<=30000;$('#share-link').value=linkOK?location.origin+location.pathname+hash:L('剪枝细节较多，请下载草稿文件分享。','This draft has extensive pruning details; share the downloaded draft file instead.');$('#copy-link').disabled=!linkOK;$('#copy-link').onclick=()=>copyText($('#share-link').value);$('#share-json').onclick=()=>download(new Blob([JSON.stringify(w.state,null,2)],{type:'application/json'}),fileTitle(w.state)+'.json');
 $('#share-original').onclick=async()=>{try{const source=w.art||await canvasBlob(await draftCanvas(w.state,1600));download(source,fileTitle(w.state)+(w.art?L('-成品','-artwork'):L('-草稿','-draft'))+'.'+(source.type==='image/png'?'png':'jpg'))}catch(e){toast(e.message)}};
 const poster=await artPoster(w);$('#share-system').disabled=false;$('#share-download').disabled=false;$('#share-download').onclick=()=>download(poster,fileTitle(w.state)+L('-分享卡.png','-share-card.png'));$('#share-system').onclick=async()=>{const file=new File([poster],fileTitle(w.state)+'.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:w.title})}else{download(poster,file.name);toast(L('分享卡已下载，可以发送给朋友。','Share card downloaded and ready to send.'))}}catch(err){if(err.name!=='AbortError')toast(L('设备分享不可用，请下载分享卡。','Device sharing is unavailable. Download the share card instead.'))}}
}
$('#art-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024)return toast(L('请选择不超过 15 MB 的 PNG、JPG 或 WebP 图片。','Choose a PNG, JPG, or WebP image no larger than 15 MB.'));const s=clone(importArtFor||state);try{const url=URL.createObjectURL(file);let img;try{img=await loadImage(url)}finally{URL.revokeObjectURL(url)}const c=document.createElement('canvas'),scale=Math.min(1,2000/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const art=await canvasBlob(c,'image/jpeg',.93),preview=await canvasBlob(await draftCanvas(s,600),'image/jpeg',.85);const artworkId=uid();await dbAction('readwrite',store=>store.put({id:artworkId,state:{...s,id:artworkId},title:s.title||file.name.replace(/\.[^.]+$/,''),updated:Date.now(),preview,art}));$('#modal').close();await refreshCount();setView('gallery');toast(L('成品已收藏，可以分享了。','Artwork saved to My Works and ready to share.'))}catch(err){toast(err.message)}finally{importArtFor=null}});
$('#draft-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>500000)return toast(L('草稿文件过大，请选择花间导出的 JSON 文件。','The draft file is too large. Choose a JSON file exported by Hanama.'));let next;try{next=validate(JSON.parse(await file.text()))}catch{return toast(L('文件无法读取，请选择花间导出的 composition.json。','The file could not be read. Choose a composition.json exported by Hanama.'))}next.id=uid();try{await activateCanvas(next,{message:L('草稿已恢复，可以继续创作。','Draft restored and ready to edit.')});$('#modal').close()}catch(err){toast(err.message)}});
icons();applyLanguage();renderMaterials();renderAll();refreshCount();if(sharedLoaded)setTimeout(()=>toast(L('已打开分享草稿，你可以继续创作。','Shared draft opened. You can continue editing.')),700);
// A shared draft may arrive as a same-page hash navigation in an already-open studio.
window.addEventListener('hashchange',async()=>{
 if(!location.hash.startsWith('#draft=')&&!location.hash.startsWith('#draft2='))return;
 let imported;try{imported=await decodeShare(location.hash)}catch{return toast(L('草稿链接无法打开，请用导出的 JSON 文件恢复。','The draft link could not be opened. Restore it from an exported JSON file.'))}imported.id=uid();history.replaceState(null,'',location.pathname+location.search);try{await activateCanvas(imported,{message:L('已打开分享草稿，剪枝与花色也一并保留。','Shared draft opened with pruning and color choices preserved.')})}catch(err){toast(err.message)}
});
